INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('highwind', 393345, '2017-10-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobota.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5hhm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Highwind', 'In Highwind you control a paper plane using only two buttons. You will destroy enemy planes and protect your own. Tapping the right side of the screen will shoot bullets and holding the left side will activate the shield. The shield blocks and reflects bullets back to your enemies. Fight different enemy planes and obstacles, each with different behavior. Travel to different dimensions and avoid obstacles on the way. As you progress through the game you will be able to purchase upgrades to your health, shield and ammo. Also, each time you beat a level you will get a power up that will help you defeat your enemies. Each time you play you will accumulate points that will unlock new planes and new game styles. Try to beat the game in each one of the different styles! Features -Simple controls: Play with only two buttons -Different game styles: Five variations of the game including an infinite mode -Minigames: Three additional sections with different mechanics -A different experience each play: Enemy waves are randomly selected from a predefined set -Upgrades and power ups: Purchase upgrades to your shield, ammo and health. Get a power up every level -Different airplanes: Unlock new airplanes with different stats' FROM games WHERE igdb_id = 393345 ON CONFLICT (game_id, language_code) DO NOTHING;
