INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trivia Vault: Classic Rock Trivia 2', 'Welcome to the Trivia Vault contestant! Play as a contestant in a gameshow called Trivia Vault Classic Rock Trivia 2 and bring your thinking hat. Answer classic rock trivia questions as quickly as you can, the faster you answer the higher the cash value. Correct answers lock in the digit code for the vault, 10 correct answers cracks the vault and awards bonus cash.' FROM games WHERE igdb_id = 54890 ON CONFLICT (game_id, language_code) DO NOTHING;
