INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ungrounded: Ripple Unleashed VR', 'Unleash your inner hero in this 16 player PvP VR arena. Fly and engage in high action aerial battles with energy blasts and charge beams. Grapple across buildings facing off against giant Titans with your two swords, or play as a Titan and crush the tiny humans going after you in this. Motion sick players be warned, this is no bars held, no teleportation, no baby steps.' FROM games WHERE igdb_id = 55456 ON CONFLICT (game_id, language_code) DO NOTHING;
