INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of the Wool Ball', 'Rise of the Wool Ball is a 2017 total conversion for the ZDoom engine. It was made by MSPaintR0cks and is the sequel to Shadow of the Wool Ball. The game is spread across three episodes, each having five levels with a secret level. Like its predecessor, Rise of the Wool Ball uses a cartoon art style, and it was named a runner-up at the Cacowards that year.' FROM games WHERE igdb_id = 195859 ON CONFLICT (game_id, language_code) DO NOTHING;
