INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meat Cleaver Mutilator', 'Janet is having a terrible weekend. Looking for a new gig, she drives to the city to the audition for a low budget horror movie. But it seems somebody has slipped a sedative in her drink. Waking up cold and alone inside an abandoned apartment building, she wonders, is this real life or just another audition?' FROM games WHERE igdb_id = 125258 ON CONFLICT (game_id, language_code) DO NOTHING;
