INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen Koi 2', 'Zen Koi 2 is a sequel to the mesmerising collection game Zen Koi that follows the Asian myth about Koi ascending into Dragons. Developed by LandShark Games, Zen Koi 2 is a free-to-play mobile game that offers an enhanced experience with new features built on the well-loved core gameplay of languid action and strategic collection. Featuring the new Dragon Realm and My Pond, you can now play with your ascended Dragon and decorate your own pond!' FROM games WHERE igdb_id = 90702 ON CONFLICT (game_id, language_code) DO NOTHING;
