INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cube Snap 2', 'Love Cube Snap but want to learn how to solve puzzles on your own? Want more than a list of turns and tired of watching videos of people explaining how to solve not your specific scramble? You are in the right place. C.S 2 will not only show you each step but explain each step. C.S 2 provides all the animated algorithms you need to practice along with a companion video to compliment many learning styles.' FROM games WHERE igdb_id = 86882 ON CONFLICT (game_id, language_code) DO NOTHING;
