INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('maze-rescue', 28381, '2017-04-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/bb5yfqdrwx9qodma05bw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/a16tkkfkyqeg9rimvxwg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maze Rescue', 'Maze Rescue is easy to play, simply draw a line with your finger and Anthony follows. The only rule is you cant cross the line, so there''s no going back. The mazes vary from level to level and also have different objectives, from the classic start to end maze to collecting items stolen from a picnic. Levels get harder the more your progress with time limits and larger more complex mazes to explore. On top of that Anthony''s friends join him and you have to guide multiple ants around the maze, each with their own objectives. Later levels include boosters that let you tackle the maze in fun new ways. From blowing up new tunnel entrances with a Cookie Crumble to teleporting to other parts of the maze with a Donut Vortex and more. If you love a challenge and doing some good then Maze Rescue is the game for you.' FROM games WHERE igdb_id = 28381 ON CONFLICT (game_id, language_code) DO NOTHING;
