INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rule-the-waves-ii', 147020, '2017-05-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zu5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9hxi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rule the Waves II', 'Rule the Waves II is the sequel to our successful game of ship design and naval battles, Rule the Waves. Whereas Rule the Waves ended by 1925, Rule The Waves II covers the entire time period from 1900 to 1955, including aricraft and aircraft carriers. Ownership of Rule the Waves is not required to be able to play Rule the Waves II. Rule the Waves II places you in the role of ''Grand Admiral'' of a navy during the first half of the 20th Century. The game is centered on designing ships and fighting naval battles, but politics, economic and foreign policy decisions will be necessary as the Player guides their navy''s deployment, construction and operations during a period of great technological innovation and political tensions. Rule the Waves is modeled on the period up to the end of the second world war, but is not intended to precisely recreate history. Rather RTW2 gives the Player the tools to lead a navy during the era when ''steam and iron'' dominated the high seas.' FROM games WHERE igdb_id = 147020 ON CONFLICT (game_id, language_code) DO NOTHING;
