INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic After the Sequel DX', 'Sonic After the Sequel DX is an enhanced re-release of Sonic After the Sequel developed by LakeFeperd that ports the Game from Multimedia Fusion Developer 2 to Clickteam Fusion 2.5, Tweaks the Game''s Physics, Adds the Drop Dash from Sonic Mania, Hardware Render Support, and a third act to Dream Dance Zone. It also features a title screen that was redrawn from scratch as Lakefeperd had learned more about pixel art from his indie game project Spark the Electric Jester.' FROM games WHERE igdb_id = 370295 ON CONFLICT (game_id, language_code) DO NOTHING;
