INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hand-and-foot-card-game', 87471, '2017-10-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/bublybupnucwuwqtudrp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pex2ctdcmg58jvom3plf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hand and Foot Card Game', 'You can now play the challenging card game Hand and Foot on your mobile device! Hand and Foot is compelling card game where each player is dealt two decks of cards: one ''hand'' and one ''foot''. The object of the game is to build melds of cards to form ''books'' which are groups of seven or more cards, score as many points as possible, and play all of the cards in your hand and foot decks as quickly as possible. The best Hand and Foot players are those who can accumulate large point totals and quickly go out which traps the other players with cards in their hands and thus leaves them with negative points.
