INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bento no Subarashisa wo Ano 2-do 3-do: Nama-ham to Yaki-udon Hen', 'In this sequel to Bento Fujiyama Tamagoyaki, players are still in the bento shop trade, but this time as a new set of protagonists. This time around, players take control of Nama-ham and Yaki-udon, a real-world eccentric two-member freelance idol band, as they take on restauranteuring. Like in the original, players can create their own custom bento by dragging and dropping ingredients. This game features a new set of three scenarios, replacing the original game''s three scenarios, and fresh background music by the band.' FROM games WHERE igdb_id = 336179 ON CONFLICT (game_id, language_code) DO NOTHING;
