INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Universe : Create Your Community', 'Prepare for a brand new adventure in Pocket Universe, a game which combines adored mechanics from strategy and RPG genres. Our vision is an experience which does not solely revolve around the player, but also the world itself which is inhabited by artificially intelligent agents. Pocket Universe tells the story of a human-created planet, following events which threatened the survival of the human race.' FROM games WHERE igdb_id = 55624 ON CONFLICT (game_id, language_code) DO NOTHING;
