INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caelum: Into the Sky', 'Caelum is a world of many wonders and treasures, in development for the HTC Vive. This world holds many secrets, and some have been unearthed by the events of the past. Some are hidden behind massive doors some behind riddles and puzzles, it is up to you to find your way and snatch up the glory and wealth. You will find yourself digging through ancient ruins, abandoned laboratories and places of great knowledge that will test your abilities and wits.' FROM games WHERE igdb_id = 91202 ON CONFLICT (game_id, language_code) DO NOTHING;
