INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conduct AR!', 'Conduct AR! is an epic augmented reality game of explosive railway action. Set in the old west you journey through diorama worlds that unfold right in front of you. Commanding trains, switching tracks and avoiding collisions, playing out in reality on the table in front of you. Look over and around landscapes, solve spatial puzzles and keep the situation under control to become the ultimate conductor in the Wild West.' FROM games WHERE igdb_id = 318365 ON CONFLICT (game_id, language_code) DO NOTHING;
