INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dot-hack-slash-slash-g-dot-u-vol-2-reminisce-hd', 182462, '2017-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7zpk.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '.Hack//G.U. Vol. 2: Reminisce HD', '.Hack//G.U. Vol. 2: Reminisce is the second entry in the .hack//G.U. series containing: Vol. 1: Rebirth, .hack//G.U. Vol. 2: Reminisce and .hack//G.U. Vol. 3: Redemption. As in the previous .hack games, .hack//G.U. simulates a massively multiplayer online role-playing game as the player controls a character who starts playing it. Players assume the role of a participant in a fictional game called The World. While in The World, the player controls the on-screen player character, Haseo, from a third-person person perspective (with optional first-person mode). The player may control the camera using the game controller''s right analog stick.' FROM games WHERE igdb_id = 182462 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 182462 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
