INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Demon''s Game: Episode 1', '"A Demon''s Game" is a very unique title, but keeps true to its horror roots, the game focuses on creating a terrifying atmosphere, rewarding exploration, and engrossing players in the rich lore of its world, moving away from the trend of incessant jump scares and low production quality is our main goal.' FROM games WHERE igdb_id = 30053 ON CONFLICT (game_id, language_code) DO NOTHING;
