INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Practisim VR', 'For the price of a match fee, you can now experience an accurate simulation of the competitive practical shooting sport. This VR experience allows you to participate in IPSC, USPSA, Pro-am and Steel Challenge matches within the comfort of your own home. It features accurate gun handling, common stage props such as swingers, movers, texas stars, polish plate rack, irish plate rack, movers and innovative stage designs.' FROM games WHERE igdb_id = 36641 ON CONFLICT (game_id, language_code) DO NOTHING;
