INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Across the Line', 'Across the Line is an immersive virtual reality experience that combines 360°video and computer generated imaging (CGI) to put viewers in the shoes of a patient entering a health center for a safe and legal abortion. Using real audio gathered at protests, scripted scenes, and documentary footage, the film is a powerful hybrid documentary-fiction depiction of the gauntlet that many abortion providers, health center staff, and patients must walk on a typical day in America.' FROM games WHERE igdb_id = 32345 ON CONFLICT (game_id, language_code) DO NOTHING;
