INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grim Tales: Graywitch', 'While researching her family’s history, your friend was pulled back in time! It’s up to you to travel into the past to find her, but it won’t be easy. There’s a mysterious monster on the prowl and the town’s history remains a mystery. Can you uncover the identity of the monster and rescue your friend in time?' FROM games WHERE igdb_id = 250592 ON CONFLICT (game_id, language_code) DO NOTHING;
