INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('last-word--1', 342169, '2017-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r3o.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Word', 'For 2017 I made Last Word, a little action word game where the difficulty increases as your words get longer. There’s a proper videogame version (with no prompt hidden inside it) here. Made in Terry’s Haxegon engine, a nice ultra-minimal Haxe library which is perfect for small prototypes. I love using engines that build to the web as well as native targets – makes it very easy to share prototypes without asking the player to do anything more annoying than play the actual game (which might already be quite annoying, honestly).
