INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IonAxxia', 'ionAXXIA is a classic space-shooter that uniquely plays the same with mouse, controller, and touch-screen through pioneering software tech. Dodge, weave, spin, shoot. Use a planet''s gravity for a speed slingshot, or draw your pursuer into a fatal collision with an explosive asteroid. This is real gameplay, dependent on reactions and skilful execution, that plays the same on your Windows tablet or phone as it does on your desktop or Steam Link.' FROM games WHERE igdb_id = 61882 ON CONFLICT (game_id, language_code) DO NOTHING;
