INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tales-of-glacier-vr', 57036, '2017-09-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobkdx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/is9yihjdseaomqlpxnqy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Glacier VR', 'It is said that there was a wonder land located in the coldest place of the earth. The indigenous people lived happily under the protect of the God. Until one day, an evil dragon came here leading its vicious corps. Destroying everything violently and expelling the residents out of their home, the evil dragon attempted to occupy the whole world. At this moment, the God came down from heaven and fought a life-and-death battle with the dragon in order to protect the residents. In the end, the dragon was defeated and fled into the ice land with its corps. The world was back in peace. To prevent the dragon from invading again, the God built a magic gate and sent guardians to garrison there. During this short peaceful time, everything was covered by cold thick ice. Turret was frozen and the magic has been weakened. The dragon from afar is getting ready for the next attack. Another protection battle is about to begin.' FROM games WHERE igdb_id = 57036 ON CONFLICT (game_id, language_code) DO NOTHING;
