INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Arashi', 'Ninja Arashi is an intense platformer with mixed RPG elements. In this game, you play as Arashi, a former legendary ninja who fights his way through the corrupted world to save his kidnapped son from the hand of the shadow devil Orochi. With superior acrobatic and deadly weapons, Arashi is ready to face menacing traps and enemies who have sworn to protect the shadow devil Orochi.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 264440 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
