INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Action Simulator', 'Grand Action Simulator - New York Car Gang is a city simulator in third person view (and FPS mode), where you drive a car or a motorbike. You play is a thug and whole city fears you. The style of city is similar to Miami of Las Vegas but actualy it''s New York. Become a chief on the streets of criminality in town. Exciting gameplay: you are waiting for the most hotspots of criminality in Vegas disctrict.' FROM games WHERE igdb_id = 361600 ON CONFLICT (game_id, language_code) DO NOTHING;
