INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Do You Think This is a Game?', 'Do You Think This is a Game? is a Yume Nikki fangame created for the 2017 Dream Diary Jam. It is a parody fangame regarding the leader of the Dream Diary Jam, Doc Saturn, jokingly threatening to ban Pyromantic from the Discord server unless they made a fangame in the next 4 hours under certain specifications (number of nexus doors, effects, and events).' FROM games WHERE igdb_id = 229271 ON CONFLICT (game_id, language_code) DO NOTHING;
