INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes Tactics', 'The world’s most addictive tactical strategy & defense game – welcome to Heroes Tactics! You’ll need some brains and tactics to lead your unique team of knights, archers, magicians, riders, flyers, and other types of awesome heroes! Strategically lead your heroes through an epic adventure as you invade exotic lands of dragons, skeletons, monsters, and citizens of the underworld. Now, begin this epic adventure to wipe out enemies, defeat other players worldwide in LIVE PVP, and rescue Princess Loralyn! GET FREE prizes everyday!' FROM games WHERE igdb_id = 37054 ON CONFLICT (game_id, language_code) DO NOTHING;
