INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mage Guard', 'Mage Guard is one of the world''s first truly gesture based spell casting games for VR. Take on the role of a Guild Mage, tasked with guarding the Guild’s most powerful relic, "The Grimoire". Being the last of its kind, you will defend it against countless waves of enemies that are trying to obtain the precious relic. Use your Magic Powers to defeat those that oppose you. Level up and gain new spell abilities to aid you in intense spell casting combat.' FROM games WHERE igdb_id = 53308 ON CONFLICT (game_id, language_code) DO NOTHING;
