INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cash Cow: Anniversary Edition', 'Save your farm and make mounds of moo-lah! Cash Cow: Anniversary Edition is an udderly upgraded and expanded edition of Cash Cow! Cash Cow makes pocket change add up to loads of fun! Help Buck the Cow and his friends save the farm in this original game of coin-counting. Combine small coins into bigger ones, and big coins into dollar bills! Use your earnings to spruce up the farm with new animals, plants, and buildings. Score big with gold nuggets and power-ups, but watch out for counterfeit coins and ladybugs!' FROM games WHERE igdb_id = 90837 ON CONFLICT (game_id, language_code) DO NOTHING;
