INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lara-croft-and-the-temple-of-osiris-gold-edition', 42930, '2017-01-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6gwe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ctkbm29vwmhdur12rq2r.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lara Croft and the Temple of Osiris: Gold Edition', 'Lara Croft and the Temple of Osiris is the sequel to the critically-acclaimed Lara Croft and the Guardian of Light, and the first-ever four-player co-op experience with Lara Croft. Featuring stunning visuals and a brand-new story, players must work together to explore the temple, defeat hordes of enemies from the Egyptian underworld, solve devious puzzles, and avoid deadly traps. All the while, players will compete for treasure, powerful artifacts, and ultimate bragging rights. Lara Croft and the Temple of Osiris takes place deep in the deserts of Egypt. In her new adventure, Lara must join forces with rival treasure hunter Carter Bell and imprisoned gods Horus and Isis, to defeat the evil god Set. As Lara and her companions fight the elements of nature across the sands and through ancient tombs, they will battle legendary deities and creatures of myth. With the fate of the world at stake, Lara must recover the fragments of Osiris to stop Set from enslaving all mankind.' FROM games WHERE igdb_id = 42930 ON CONFLICT (game_id, language_code) DO NOTHING;
