INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shantae: Half-Genie Hero - Risky Beats Edition', 'Shantae: Half-Genie Hero, stylized as Shantae: ½ Genie Hero, is a platform video game developed by WayForward Technologies for Microsoft Windows, PlayStation 4, PlayStation Vita, Wii U, and Xbox One. It is the fourth game in the Shantae series, following Shantae and the Pirate''s Curse, and the first to be specifically developed for high definition game platforms. The game was released in December 2016.' FROM games WHERE igdb_id = 51140 ON CONFLICT (game_id, language_code) DO NOTHING;
