INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elaine', 'This is elaine! A minimalistic tile-matching action game by Slight Super Powers. In this deceptively simple game, you''ll have to deal with a shifting screen, multi-colored patterns of increasing speed and complexity, and an unrelenting countdown timer synced to brain-pumping music.' FROM games WHERE igdb_id = 29596 ON CONFLICT (game_id, language_code) DO NOTHING;
