INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('undead-breakout', 196625, '2017-10-06', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undead Breakout', 'In Undead Breakout, you must use the pathways and thoroughfares in the ruins of a resort town, Paris and New York City to move survivors to escape points (indicated by a gold star). Each level provides a variety of challenges in which you have to move the gold survivors around the board like pieces on a game board, avoiding the zombies that will try to overtake the survivors and the spreading infection. Each zombie and each survivor type has different characteristics that impact their movement and movement speed. To aid survivors, some missions incorporate police officers or soldiers who can protect the survivors. The soldiers can create a protected spot by holding zombies back a space. Police officers can be used sacrificially to kill one zombie they encounter although the officer will die in the process. Think strategically to reach each goal and survive the undead masses.' FROM games WHERE igdb_id = 196625 ON CONFLICT (game_id, language_code) DO NOTHING;
