INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Go', 'Go is a 3000-year-old game of strategy played by over 24 million people world-wide. Play is simple, place stones at key positions to surround territory and capture enemies. The rules can be learned in minutes, but Go has yet to be completely mastered. Ancient Go is designed for new players.' FROM games WHERE igdb_id = 32714 ON CONFLICT (game_id, language_code) DO NOTHING;
