INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cerberus Project', 'Most FPSes nowadays are just mindless clicker games with guns. The Cerberus Project rejects all of the dumbing down of the last 15 years, and instead builds on the greatest FPS games with unique features such as analog sword movement, original weapons, and new types of enemies.' FROM games WHERE igdb_id = 41932 ON CONFLICT (game_id, language_code) DO NOTHING;
