INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter II: 30th Anniversary Edition', 'The 30th Anniversary Edition of Street Fighter II published by iam8bit is the original game on a brand-new playable SNES cartridge in a tri-fold box w/ foil, gloss and embossments. Limited to a total of 5500 copies, of which 4500 copies come in Opaque Ryu Headband Red and 1000 copies come in Translucent, Glow-in-the-Dark Blanka Green. The original manual has been worked over and includes mini posters. The tri-fold packaging doubles as a mini poster when opened up.' FROM games WHERE igdb_id = 195933 ON CONFLICT (game_id, language_code) DO NOTHING;
