INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ty-the-tasmanian-tiger-2-bush-rescue-hd', 147845, '2017-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55cm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc0w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TY the Tasmanian Tiger 2: Bush Rescue HD', 'TY puts the BOOM in BOOMERANG! TY the Tasmanian Tiger 2: Bush Rescue is the sequel to Krome Studios'' charming Australiana-themed videogame. This classic platformer, updated for Nintendo Switch, features more rangs, more vehicles, more bots, and more EVERYTHING... in an open world Aussie Adventure. Throw boomerangs, bite, smash and glide your way around the Australian Outback and stop the evil plans of the wicked Boss Cass and help the good folk of the little country town of BURRAMUDGEE. This sequel to the popular TY the Tasmanian Tiger is a game on a grander scale. In addition to classic platforming elements, you''ll fight Aussie bush fires from a helicopter, drive around Southern Rivers while hanging on to the back of a four-wheel drive and use the bots to defeat enemies and solve puzzles - all while trying to find a variety of different collectables. And now, only on the HD remaster, you can customize TY''s looks, and best of all there are two brand NEW never before seen boomerangs.' FROM games WHERE igdb_id = 147845 ON CONFLICT (game_id, language_code) DO NOTHING;
