INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos;Child Love Chu Chu!!', 'Chaos;Child Love Chu Chu!! is a visual novel video game. Is a spin-off from the 2014 game Chaos;Child, and part of the larger Science Adventure series. The story, which is affected by player choices, is set in Shibuya, Tokyo, and follows Takuru Miyashiro, who ignores the "Reincarnation of the New Generation of Madness" events, instead focusing on spending time with girls.' FROM games WHERE igdb_id = 65530 ON CONFLICT (game_id, language_code) DO NOTHING;
