INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saga of the Nine Worlds: The Gathering', 'A peaceful morning in Midgard is rocked by a dragon attack! You quickly set out with your princess to track down the beast and destroy it, but are attacked along the way. You should have died… but you were saved. It seems the gods have chosen you for a very special task – save the world! The gods believe you are worthy. Now you need only prove it. Gather your companions and set out on a journey through the mythical Nine Worlds in this this epic hidden-object puzzle adventure game!' FROM games WHERE igdb_id = 74311 ON CONFLICT (game_id, language_code) DO NOTHING;
