INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Pet Rock', 'My Pet Rock is a top down planet defense with rogue-lite, bullet-hell, and arcade elements. You are tasked with defending a rock against endless waves of miners and other hostile enemies, as well as fighting difficult bosses. Game play becomes increasingly harder and chaotic but more rewarding as you progress. Buy items and collect pickups to counter the ever increasing difficulty of the enemies.' FROM games WHERE igdb_id = 30456 ON CONFLICT (game_id, language_code) DO NOTHING;
