INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skyraine', 'Skyraine is an action packed platform/missile defender game. Defend against waves of enemies in your turret, and use special power-ups to annihilate the stronger hordes. Leave your turret to strategically expand your base between waves. Play with up to 3 players in local multiplayer co-op. Will you survive?' FROM games WHERE igdb_id = 53616 ON CONFLICT (game_id, language_code) DO NOTHING;
