INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spacecats with Lasers', 'In this twin-stick shooter the evil space rats locked you up in their space arena and your only hope is to fight as many waves as possible. Help your Spacecat to survive with the help of  several perks and powerups. Did you ever want to have a cat dressed as a unicorn on top of a burrito shooting explosive and chain-lightning lasers at evil rodents? Then this just might be your game!' FROM games WHERE igdb_id = 36531 ON CONFLICT (game_id, language_code) DO NOTHING;
