INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marty Thinks 4th Dimensionally', 'Marty Thinks 4th Dimentionally is an isometric 3D puzzle platformer where you play as a small robot on a journey to find his creator. With the aid of time travel, Marty is able to step into the past and work together with past versions of himself to overcome any challenge. By playing out partial solutions and then resetting time, the player can work with their past to succeed. 
