INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BoostBots VR', 'A fully destructible voxel based Virtual Reality experience on the HTC VIVE. Giving players the mobility to fluidly move in three dimensional space and the firepower and blast out every voxel of every level! Key VR mobility aspects such as the Short-Hop, Boost, 3D Breaking and Drift breaking give the VR warrior various levels of control to maintain more accurate and controlled boosting flow.' FROM games WHERE igdb_id = 54841 ON CONFLICT (game_id, language_code) DO NOTHING;
