INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All-Star Fielding Challenge VR', 'All-Star Fielding Challenge VR is an exciting baseball fielding simulator that puts you at shortstop as you attempt to field line-drives, pop-ups, and ground balls. Catch enough balls to progress through each round and achieve greatness as you climb the leaderboard. Casual to hardcore baseball fans will enjoy this fast-paced arcade style baseball action of All-Star Fielding Challenge VR.' FROM games WHERE igdb_id = 29406 ON CONFLICT (game_id, language_code) DO NOTHING;
