INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout 4: Game of the Year Pip-Boy Edition', 'In addition to including the award-winning original game and official add-ons, Fallout 4 G.O.T.Y. Pip-Boy Edition includes: Pip-Boy Replica and Stand. This wearable device faithfully replicates the in-game model and comes complete with RobCo Industries stand, adjustable foam cuff, rotating knobs and lights. Designed to accommodate a variety of smartphone devices with customizable foam inserts, the Pip-Boy is the ultimate accessory for the official Pip-Boy companion mobile app that allows players to manage their in-game inventory, perks, holotapes, and more.' FROM games WHERE igdb_id = 72379 ON CONFLICT (game_id, language_code) DO NOTHING;
