INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tequila Zombies 3', 'Tequila Zombies 3 is a platform shooter. Zombie apocalypse strikes hard. Zombies, vampires and demons spread all over the world. But there is still hope... guns... and alcohol! So there is still a chance to survive. Kill all zombies, drink all tequila!' FROM games WHERE igdb_id = 29353 ON CONFLICT (game_id, language_code) DO NOTHING;
