INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World In Danger', 'World In Danger is a top-down action game with stealth elements, similar to classics such as "Metal Gear". Embark on missions across the globe, taking out groups of enemies, rescuing hostages, disarming bombs and more. Face the unique and challenging boss fights the player encounters as the story unravels in this over the top action extravaganza.' FROM games WHERE igdb_id = 27178 ON CONFLICT (game_id, language_code) DO NOTHING;
