INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of DASM: DASM Spell Quest', 'Know someone that is struggling with their ABC''s or basic spelling? Do they have a short attention time span? Want a program that all students or children can use in the same classroom and can tailor make it to their needs and levels? Well here it is, DASM Spell Quest!' FROM games WHERE igdb_id = 36637 ON CONFLICT (game_id, language_code) DO NOTHING;
