INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('little-triangle', 29985, '2017-01-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co253y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardbw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Triangle', 'The game targets to be one of the best hardcore platformers ever. If you are worried that a good hardcore game will take you too long to finish, you can try the "casual" mode in Little Triangle where you have some additional lives. With the same level design as the hardcore mode, you will still find the fun in the challenges with much less pressure. If you only love highly challenging hardcore platformers but cannot find new ones, please check the "hardcore" mode of Little Triangle and the difficult level is just right for you.' FROM games WHERE igdb_id = 29985 ON CONFLICT (game_id, language_code) DO NOTHING;
