INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire the Masquerade: We Eat Blood', 'Told entirely from a mobile messaging perspective, We Eat Blood is a sharp, mature and often terrifying story about your first nights as unwilling predator and prey. Hunted by unknown enemies and driven by an alien hunger, will you sever your ties with the mortal world or try to cling to your former life? Will you join ancient conspiracies, or turn the tables on forces older than the written word? Terrible power lies within your grasp, but there is always a price to pay.' FROM games WHERE igdb_id = 27424 ON CONFLICT (game_id, language_code) DO NOTHING;
