INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All-in-One Mahjong 2', 'All-in-One Mahjong 2 is a relaxing tile-matching puzzle game where players clear the board by pairing identical tiles. Featuring 48 unique layouts and 12 soothing backgrounds, the game offers two modes: Timed Mode with shuffle options and Score Mode for strategic play. With tranquil music and intuitive gameplay, it''s designed for casual players seeking a meditative Mahjong experience.' FROM games WHERE igdb_id = 89225 ON CONFLICT (game_id, language_code) DO NOTHING;
