INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Quiz Room', 'The Quiz Room is an educational game by the New South Wales government about drug and alcohol use. The game plays as a trivia cube where you are given various multiple choice questions about negative side affects of drugs and alcohol and you have to answer them correctly to fill out each side of the cube. The game ends after each side of the cube is complete, or after you get 3 incorrect answers.' FROM games WHERE igdb_id = 228657 ON CONFLICT (game_id, language_code) DO NOTHING;
