INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragons Online Ultra', 'Create your Dragon, then fly, run and shoot with players around the world! Team up to fight fantasy bosses or verse each other! Rank up and increase your stats to make your character faster and stronger! Huge amounts of customisation''s and options for both the Game and your Dragon! Other features include: In-game chat, Nest claiming, NPC''s, Eggs and Hatchlings, Special free Daily changing skin, photo mode button.' FROM games WHERE igdb_id = 187753 ON CONFLICT (game_id, language_code) DO NOTHING;
