INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Prophet', 'Final Prophet is a 2d top down action adventure. Inspired by one of, if not the greatest game of all time The Legend Of Zelda NES. Your adventure takes place on the northern continent of Contrarious. The Darkness has emerged from the shadow and is now laying siege to the world. The Council of Prophets have been captured by the darkness, other masters and apprentices have either been destroyed or taken hostage. You are the only hope left in the world. You must go out, find the council members and destroy the darkeness, You are the Final Prophet.' FROM games WHERE igdb_id = 37420 ON CONFLICT (game_id, language_code) DO NOTHING;
