INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tens Junior Maths IQ Challenge', 'Train your powers of mental arithmetic to clear each level by matching tiles to reach the target value in a fun, kid‑friendly educational puzzle. Difficulty scales from easy to hard, with a tutorial for quick onboarding. Track progress with per‑level math IQ ratings, play endlessly as difficulty ramps up, and manage up to 32 user profiles for classrooms or families. Use earned freebies to reveal solutions when you get stuck, and enjoy playful “musical numbers” designed to engage younger players.' FROM games WHERE igdb_id = 103993 ON CONFLICT (game_id, language_code) DO NOTHING;
