INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love or Die', 'Love or Die is a horror parody visual novel made as a fun and short Halloween game. You will play as a human transfer student who needs to find a date before the Halloween Dance at Tap School. But wait, turns out not all students who attend the school are humans! Vampires, witches, werecats and even zombies?! And what''s with that weird voice in your head? Oh boy, oh boy, try not to get yourself killed before the fun part begins~' FROM games WHERE igdb_id = 124041 ON CONFLICT (game_id, language_code) DO NOTHING;
