INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ARC Continuum', 'ARC Continuum is a third person action adventure set on Taraan, a desert planet with a mystical energy at its core that powers the ARC - a device that allows you to control and manipulate the fabric of time. Take the role of our hero, Hadrian who is thrust into the midst of a revolution on the rise, where he must master the powers of time to free his people from the bondages of oppression from the evil Kasaar.' FROM games WHERE igdb_id = 27671 ON CONFLICT (game_id, language_code) DO NOTHING;
