INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Tales: The House of Others', 'Your brother is the host of Ghost Riders – a popular ghost hunting TV show, but one night you receive a strange package that forewarns his death! You’ll need your special astral glasses to help you view the past and interact with the astral plane, but first you’ll have to find them! Travel to the haunted mansion of a serial killer and unwrap this unsolved ghost story, before you and your brother become the next chapter of it in this haunting hidden-object puzzle adventure game!' FROM games WHERE igdb_id = 181645 ON CONFLICT (game_id, language_code) DO NOTHING;
